import '../models/result_model.dart'; import '../services/firestore_service.dart'; class ResultRepository { final FirestoreService service; ResultRepository({FirestoreService? service}):service=service??FirestoreService(); Future<void> save(ResultModel x)=>service.setDoc('results',x.id,x.toMap()); Stream<List<ResultModel>> byStudent(String id)=>service.stream('results').map((s)=>s.docs.map((d)=>ResultModel.fromMap(d.id,d.data())).where((r)=>r.studentId==id).toList()); }